/// Returned when a quoted field is not closed before the end of the record.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct UnterminatedQuote;

/// Splits one CSV record into its fields.
pub fn split_record(line: &str) -> Result<Vec<String>, UnterminatedQuote> {
    let chars: Vec<char> = line.chars().collect();
    let mut fields = Vec::new();
    let mut field = String::new();
    let mut in_quotes = false;
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if in_quotes {
            if c == '"' {
                if i + 1 < chars.len() && chars[i + 1] == '"' {
                    field.push('"');
                    i += 1;
                } else {
                    in_quotes = false;
                }
            } else {
                field.push(c);
            }
        } else if c == '"' {
            in_quotes = true;
        } else if c == ',' {
            fields.push(field);
            field = String::new();
        } else {
            field.push(c);
        }
        i += 1;
    }
    if in_quotes {
        return Err(UnterminatedQuote);
    }
    if !field.is_empty() {
        fields.push(field);
    }
    Ok(fields)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn plain_fields() {
        assert_eq!(split_record("a,b,c").unwrap(), ["a", "b", "c"]);
    }

    #[test]
    fn quoted_comma() {
        assert_eq!(split_record("\"x,y\",z").unwrap(), ["x,y", "z"]);
    }
}

