use fixture::{UnterminatedQuote, split_record};

fn ok(line: &str) -> Vec<String> {
    split_record(line).unwrap_or_else(|_| panic!("{line:?} should parse"))
}

#[test]
fn keeps_every_field() {
    assert_eq!(ok("a,b,c"), ["a", "b", "c"]);
    assert_eq!(ok("a,,c"), ["a", "", "c"]);
    assert_eq!(ok("a,"), ["a", ""]);
    assert_eq!(ok(",a"), ["", "a"]);
    assert_eq!(ok(","), ["", ""]);
    assert_eq!(ok(""), [""]);
    assert_eq!(ok(" a , b "), [" a ", " b "]);
}

#[test]
fn quoted_fields() {
    assert_eq!(ok("\"x,y\",z"), ["x,y", "z"]);
    assert_eq!(ok("\"\""), [""]);
    assert_eq!(ok("a,\"\""), ["a", ""]);
    assert_eq!(ok("\"say \"\"hi\"\"\",b"), ["say \"hi\"", "b"]);
    assert_eq!(ok("\"\"\"\""), ["\""]);
    assert_eq!(ok("\"a\nb\",c"), ["a\nb", "c"]);
}

#[test]
fn quote_inside_unquoted_field_is_literal() {
    assert_eq!(ok("ab\"c,d"), ["ab\"c", "d"]);
    assert_eq!(ok("5\" disk,x\""), ["5\" disk", "x\""]);
}

#[test]
fn strips_one_line_terminator() {
    assert_eq!(ok("a,b\n"), ["a", "b"]);
    assert_eq!(ok("a,b\r\n"), ["a", "b"]);
    assert_eq!(ok("a,\n"), ["a", ""]);
    assert_eq!(ok("\n"), [""]);
    assert_eq!(ok("\"x\r\n\"\r\n"), ["x\r\n"]);
}

#[test]
fn unterminated_quote_is_an_error() {
    assert_eq!(split_record("\"abc"), Err(UnterminatedQuote));
    assert_eq!(split_record("a,\"b,c"), Err(UnterminatedQuote));
    assert_eq!(split_record("\"a\"\""), Err(UnterminatedQuote));
}
